import{R as r,e as o,f as t,U as n}from"./chunks/framework.BKStFnx-.js";const f=JSON.parse('{"title":"Web Components","description":"","frontmatter":{},"headers":[],"relativePath":"web-components/index.md","filePath":"web-components/index.md","lastUpdated":1780377007000}'),a={name:"web-components/index.md"};function s(d,e,i,l,m,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="web-components" tabindex="-1">Web Components <a class="header-anchor" href="#web-components" aria-label="Permalink to &quot;Web Components&quot;">​</a></h1><p>Use <code>@verbb/formie-web-components</code> when you want portable custom elements around Formie: <strong>server-rendered forms</strong> (server-rendered form markup) or <strong>client-rendered forms</strong> (client-rendered UI in <code>&lt;formie-core-form&gt;</code>).</p><p>If you want to see the full Web Components integration in action, use the <a href="https://formie-starters.verbb.io/web-components" target="_blank" rel="noreferrer">Web Components starter</a> as a complete example app.</p><p>The package exposes two hosts:</p><ul><li><strong><code>formie-form</code></strong> — server-rendered forms via <code>@verbb/formie-browser</code> (themes, server-rendered markup, browser events).</li><li><strong><code>formie-core-form</code></strong> — Definition + <code>@verbb/formie-core</code> form engine (REST/GraphQL envelope load, client-rendered field tree, optional registry overrides for custom elements).</li></ul><p>If Craft is already rendering the final form HTML directly into the page and you do not need a custom element at the mount point, use the <a href="/formie/browser/">Browser</a> docs instead.</p><h2 id="server-rendered-forms" tabindex="-1">Server-rendered Forms <a class="header-anchor" href="#server-rendered-forms" aria-label="Permalink to &quot;Server-rendered Forms&quot;">​</a></h2><p>Use server-rendered forms when:</p><ul><li>you want a plain HTML/JS embed and Formie-owned markup</li><li>you want the browser package theme, events, and modules</li><li><strong><code>formie-form</code></strong> is enough for your mount story</li></ul><p>Server-rendered forms come in these shapes:</p><ul><li><strong>Declarative</strong> <code>&lt;formie-form transport=&quot;rest&quot; …&gt;</code> (attributes and/or properties)</li><li><strong>Imperative</strong> <code>document.createElement(&#39;formie-form&#39;)</code> and set properties</li><li><strong><code>createFormieClient()</code></strong> when you need the full browser client without the <code>formie-form</code> wrapper</li></ul><p>Those are the same server-rendered browser behavior, not different products.</p><p>Start with <a href="/formie/web-components/server-rendered/overview">Server-rendered</a>.</p><h2 id="client-rendered-forms" tabindex="-1">Client-rendered Forms <a class="header-anchor" href="#client-rendered-forms" aria-label="Permalink to &quot;Client-rendered Forms&quot;">​</a></h2><p>Use client-rendered forms when:</p><ul><li>you want <code>&lt;formie-core-form&gt;</code> to render the form UI</li><li>you are fine styling that output yourself (or reusing class names from the default renderer)</li><li>you may replace pieces with <strong>custom elements</strong> via <code>FormieRegistry</code> (whole <strong>field</strong> hosts, field controls only, optional layout regions)</li></ul><p>The element loads the client definition envelope from <code>endpoint</code> + <code>form-handle</code> (REST or GraphQL). It does not currently accept a preloaded envelope attribute; for fully custom loading, use <code>@verbb/formie-core</code> in JavaScript.</p><p>Start with <a href="/formie/web-components/client-rendered/overview">Client-rendered forms</a>.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h2><h3 id="server-rendered-forms-formie-form" tabindex="-1">Server-rendered forms (<code>formie-form</code>) <a class="header-anchor" href="#server-rendered-forms-formie-form" aria-label="Permalink to &quot;Server-rendered forms (`formie-form`)&quot;">​</a></h3><p>Use <strong>REST</strong> when you want the simplest path: Craft base URL or render URL, standard browser submit after paint.</p><p>Use <strong>GraphQL</strong> when the initial HTML payload should come from your GraphQL layer. Submit still uses the rendered form POST unless you change strategy at the browser layer.</p><p>Set <code>transport</code> and <code>endpoint</code> on <code>&lt;formie-form&gt;</code> (or as properties). For object options such as <code>themeConfig</code> or a preloaded <code>payload</code>, use <strong>JavaScript properties</strong> on the element or <code>createFormieClient()</code>.</p><h3 id="client-rendered-forms-formie-core-form" tabindex="-1">Client-rendered forms (<code>formie-core-form</code>) <a class="header-anchor" href="#client-rendered-forms-formie-core-form" aria-label="Permalink to &quot;Client-rendered forms (`formie-core-form`)&quot;">​</a></h3><p>Use <strong>REST</strong> when you want the default client definition envelope load and submit flow against Formie’s frontend actions.</p><p>Use <strong>GraphQL</strong> when the envelope and mutations should go through GraphQL; Formie uses GraphQL for submit, session refresh, and page changes when <code>transport=&quot;graphql&quot;</code>.</p><p>See <a href="/formie/web-components/client-rendered/overview">Client-rendered forms — Overview</a> for the GraphQL query shape and mutation names.</p>',27)])])}const h=r(a,[["render",s]]);export{f as __pageData,h as default};
